#include <bits/stdc++.h>
using namespace std;struct E{int f,t,a,c;vector<int>I,O;};struct N{int p;vector<int>r;int par,ei;bool live;};
int main(int ac,char**av){ifstream f(av[1]);int m,np,ne,ni,ng;f>>m>>np>>ne>>ni>>ng;int d=m*5;vector<int>initial(ni);for(auto&x:initial)f>>x;vector<vector<vector<int>>>goals(np);for(int j=0,p;j<ng;j++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals[p].push_back(r);}vector<E>es(ne);vector<vector<int>>adj(np);for(int j=0;j<ne;j++){auto&e=es[j];f>>e.f>>e.t>>e.a>>e.c;e.I.resize(d);e.O.resize(m);for(auto&x:e.I)f>>x;for(auto&x:e.O)f>>x;assert(f&&e.c>=0&&e.c<=4);adj[e.f].push_back(j);}int cap=ac>2?stoi(av[2]):3;size_t limit=ac>3?stoull(av[3]):1000000;vector<N>ns;vector<vector<int>>B(np);size_t retired=0,cmp=0;int hit=-1;auto le=[&](const vector<int>&a,const vector<int>&b){cmp++;for(int i=0;i<d;i++)if(a[i]>b[i])return false;return true;};auto step=[&](const E&e,const vector<int>&mark,vector<int>&rr,int cap){for(int k=0;k<d;k++)if(mark[k]<e.I[k])return false;for(int z=0;z<m;z++){int o=5*z;int ages[5],need[5],after[5]={};for(int j=0;j<5;j++){ages[j]=mark[o+j]-(j<4?mark[o+j+1]:0);need[j]=e.I[o+j]-(j<4?e.I[o+j+1]:0);}for(int j=4;j>=0;j--)for(int k=j;k<5&&need[j];k++){int t=min(need[j],ages[k]);need[j]-=t;ages[k]-=t;}for(int j=0;j<5;j++){assert(!need[j]);after[min(4,j+e.c)]+=ages[j];}after[e.c]+=e.O[z];for(int j=3;j>=0;j--)after[j]+=after[j+1];for(int j=0;j<5;j++)rr[o+j]=min(cap,after[j]);}return true;};auto add=[&](int p,const vector<int>&r,int par,int ei){auto&v=B[p];for(int id:v)if(ns[id].live&&le(r,ns[id].r))return;for(int id:v)if(ns[id].live&&le(ns[id].r,r)){ns[id].live=false;retired++;}if(v.size()>32){vector<int>w;for(int id:v)if(ns[id].live)w.push_back(id);v.swap(w);}int id=ns.size();ns.push_back({p,r,par,ei,true});v.push_back(id);for(auto&g:goals[p])if(le(g,r))hit=id;};for(int p:initial)add(p,vector<int>(d),-1,-1);size_t next=ns.size();int depth=0;
for(size_t k=0;k<ns.size()&&hit<0;k++){if(k==next){depth++;next=ns.size();cerr<<"depth "<<depth<<" labels "<<ns.size()<<" live "<<ns.size()-retired<<" comparisons "<<cmp<<"\n";}if(!ns[k].live)continue;int p=ns[k].p;auto r=ns[k].r;for(int ei:adj[p]){auto&e=es[ei];vector<int>v(d);if(!step(e,r,v,cap))continue;add(e.t,v,k,ei);if(ns.size()>=limit){cout<<"status CAP labels "<<ns.size()<<" depth "<<depth<<"\n";return 0;}if(hit>=0)break;}}
if(hit<0){cout<<"status NO_LOSSY_WITNESS labels "<<ns.size()<<" live "<<ns.size()-retired<<" depth "<<depth<<"\n";return 0;}
cout<<"status AGE_PETRI_WITNESS labels "<<ns.size()<<" depth "<<depth<<" saturation "<<cap<<"\n";vector<int>path;for(int u=hit;u>=0;u=ns[u].par)path.push_back(u);reverse(path.begin(),path.end());cout<<"start "<<ns[path[0]].p<<"\n";vector<int>mark(d);for(int u:path){auto&n=ns[u];if(n.par<0)continue;auto&e=es[n.ei];cout<<"EDGE "<<n.ei<<" "<<e.f<<" "<<e.t<<" "<<e.a;for(auto x:mark)cout<<" "<<x;cout<<"\n";vector<int>rr(d);assert(step(e,mark,rr,INT_MAX));mark.swap(rr);}cout<<"goal "<<ns[hit].p;for(auto x:mark)cout<<" "<<x;cout<<"\n";bool ok=false;for(auto&g:goals[ns[hit].p])if(le(g,mark))ok=true;assert(ok);}
